   461→export function EditDictionaryDialog({open, onOpenChange, type, item}: EditDictionaryDialogProps) {
   462→    const category = getCategory(type);
   463→    const updateMutation = useUpdateDictionary();
   464→
   465→    // Form state
   466→    const [keyword, setKeyword] = useState("");
