   469→
   470→    // Validation
   471→    const [errors, setErrors] = useState<string[]>([]);
   472→
   473→    // Initialize form when item changes
   474→    useEffect(() => {
   475→        if (item) {
   476→            setKeyword(item.keyword || "");
   477→            // SET types store word in keyword field, other types use value
   478→            if (category === 'SET') {
   479→                setValue(item.keyword || "");
   480→            } else {
   481→                setValue(item.value || "");
   482→            }
   483→            setSynonymDirection(item.keyword === null ? 'bidirectional' : 'unidirectional');
   484→            setErrors([]);
   485→        }
   486→    }, [item, category]);
   487→
   488→    const validate = (): boolean => {
   489→        const newErrors: string[] = [];
   490→
   491→        if (category === 'SET') {
   492→            if (!value.trim()) {
   493→                newErrors.push("단어를 입력해주세요.");
   494→            }
   495→        } else if (category === 'SYNONYM') {
   496→            if (type === 'SYNONYM') {
   497→                if (synonymDirection === 'bidirectional') {
   498→                    const synonyms = parseCommaSeparated(value);
   499→                    if (synonyms.length < 2) {
   500→                        newErrors.push("양방향 동의어는 최소 2개 이상 입력해주세요.");
   501→                    }
   502→                } else {
   503→                    if (!keyword.trim()) {
   504→                        newErrors.push("대표 단어를 입력해주세요.");
   505→                    }
   506→                    if (!value.trim()) {
   507→                        newErrors.push("동의어 목록을 입력해주세요.");
   508→                    }
   509→                    const synonyms = parseCommaSeparated(value);
   510→                    if (synonyms.includes(keyword.trim())) {
   511→                        newErrors.push("대표 단어가 동의어 목록에 포함될 수 없습니다.");
   512→                    }
   513→                }
   514→            } else {
   515→                if (!keyword.trim()) {
   516→                    newErrors.push("대상 표현을 입력해주세요.");
   517→                }
   518→                if (!value.trim()) {
   519→                    newErrors.push("정규화 기호를 입력해주세요.");
   520→                }
   521→            }
   522→        } else if (category === 'MAP') {
   523→            if (!keyword.trim()) {
   524→                newErrors.push(type === 'SPACE' ? "붙여쓴 말을 입력해주세요." : "복합어를 입력해주세요.");
   525→            }
   526→            if (type === 'SPACE' && keyword.includes(' ')) {
   527→                newErrors.push("붙여쓴 말에는 공백이 포함될 수 없습니다.");
   528→            }
   529→            if (!value.trim()) {
   530→                newErrors.push(type === 'SPACE' ? "분리 결과를 입력해주세요." : "분해 결과를 입력해주세요.");
   531→            }
   532→            const parts = parseCommaSeparated(value);
   533→            if (parts.length < 2) {
   534→                newErrors.push("결과는 최소 2개 이상의 단어여야 합니다.");
   535→            }
   536→        }
   537→
   538→        setErrors(newErrors);
   539→        return newErrors.length === 0;
   540→    };
   541→
   542→    const handleSubmit = async () => {
   543→        if (!item || !validate()) return;
   544→
   545→        try {
   546→            let finalKeyword: string | null = null;
   547→            let finalValue: string | null = null;
   548→
   549→            if (category === 'SET') {
